import test from 'node:test';import assert from 'node:assert/strict';import {farmPlants,farmStations,farmObjects,farmCategories,defaultFarm,normalizeFarm,farmView,farmAction,farmArtKey,farmArt,farmArtKeys,farmExperiments} from '../src/farm.js';import {objects,materials} from '../src/data.js';import {zones,zoneExit} from '../src/zones.js';import {pathfind,cellAt,blocked} from '../src/navigation.js';import {getJournalEntries} from '../src/journal.js';
test('farm approaches are reachable without walking through fixtures; hub routing selects the correct gate',()=>{const points=[zones.farm.spawn,...farmObjects.map(o=>[o.x-65,o.y+55])];for(const a of points)for(const b of points){const p=pathfind(a,b,'farm');if(cellAt(...a).join()!==cellAt(...b).join())assert.ok(p.length,`${a} to ${b}`);for(const xy of p)assert.equal(blocked(...cellAt(...xy),'farm'),false)}assert.equal(zoneExit('hq','farm'),'hq-farm');assert.equal(zoneExit('grounds','farm'),'home');assert.equal(zoneExit('farm','grounds'),'farm-exit')});
test('fifteen categorized plants have reachable sample trays; duplicate collecting keeps one sample',()=>{assert.equal(farmPlants.length,15);assert.equal(new Set(farmPlants.map(p=>p.id)).size,15);for(const [tag]of farmCategories)assert.ok(tag==='all'||farmPlants.some(p=>p.tags.includes(tag)));let f=defaultFarm();for(const p of farmPlants){assert.ok(objects.some(o=>o.zone==='farm'&&o.id==='farm-'+p.site));let r=farmAction(f,{type:'collect',id:p.id});f=r.farm;r=farmAction(f,{type:'collect',id:p.id});assert.equal(r.farm.seeds.filter(id=>id===p.id).length,1)}assert.equal(f.seeds.length,15);assert.equal(normalizeFarm({seeds:['bad','bean','bean'],growth:100}).seeds.length,1);assert.equal(normalizeFarm({growth:100}).growth,0)});
test('every farm page action remains within six native choices, and all listing pages are reachable',()=>{const seen=new Set(),queue=['home','hydro','biodome','growth','orchard','vertical','solar','water','power','bank','leaf','robot','pollination','recycle',...['garden','hydro','biodome','orchard','vertical'].map(s=>'tray:'+s+':0')];const f={...defaultFarm(),seeds:farmPlants.map(p=>p.id)};while(queue.length){const route=queue.shift();if(seen.has(route))continue;seen.add(route);const v=farmView(f,route);assert.ok(v.title&&v.body&&v.visual);assert.ok(v.actions.length<=6,route);assert.ok(farmArtKeys.includes(farmArtKey(f,route)));assert.ok(farmArt(farmArtKey(f,route)).startsWith('<svg'));for(const a of v.actions){assert.ok(a.label&&a.action.type);if(a.action.type==='page')queue.push(a.action.route);}}for(const p of farmPlants)assert.ok(seen.has('plant:'+p.id));assert.ok(seen.has('list:seeds:0'));assert.ok(seen.has('list:nuts:0'));assert.ok(seen.has('bank:all:4'))});
test('all experiments can complete and repeat without time, scores or seed consumption',()=>{let f=defaultFarm();for(const key of ['pump','shade','sun'])f=farmAction(f,{type:'toggle',key}).farm;for(const [key,n]of [['growth',5],['pollen',3],['water',4],['recycle',3],['zoom',3],['robot',3]])for(let i=0;i<n;i++)f=farmAction(f,{type:'step',key}).farm;assert.deepEqual(new Set(f.experiments),new Set(Object.keys(farmExperiments)));for(let i=0;i<12;i++)f=farmAction(f,{type:'step',key:'growth'}).farm;assert.equal(f.experiments.length,9);assert.equal(f.seeds.length,0);const entries=getJournalEntries('experiments',new Set(),new Set(),objects,materials,f);assert.equal(entries.length,9);assert.ok(entries.every(e=>objects.some(o=>o.id===e.target)));const seedState=farmAction(f,{type:'collect',id:'bean'}).farm;assert.ok(getJournalEntries('found',new Set(),new Set(),objects,materials,seedState).some(e=>e.id==='seed-bean'))});
